const task = $json.body;
const comentarios = task.fields.comment.comments;
const ultimoComentario = comentarios[comentarios.length - 1];

return [{
  json: {
    task: {
      key: task.key,
      titulo: task.fields.summary,
      descricao: task.fields.description,
      status: task.fields.status.name,
      prioridade: task.fields.priority.name,
      tipo: task.fields.issuetype.name,
      projeto: task.fields.project.name,
      criador: task.fields.creator.displayName,
      responsavel: task.fields.assignee?.displayName ?? null,
    },
    comentario: {
      autor: ultimoComentario.author.displayName,
      texto: ultimoComentario.body
  .replace(/\[~accountid:[^\]]+\]/g, '')
  .trim(),
      horario: new Date(ultimoComentario.created).toLocaleString("pt-BR", {
        timeZone: "America/Sao_Paulo",
      }),
    },
  },
}];

const task = $json.body;

return [{
  json: {
    id: task.id,
    key: task.key,
    url: task.self,

    titulo: task.fields.summary,
    descricao: task.fields.description,

    tipo: {
      id: task.fields.issuetype.id,
      nome: task.fields.issuetype.name
    },

    projeto: {
      id: task.fields.project.id,
      key: task.fields.project.key,
      nome: task.fields.project.name,
      tipo: task.fields.project.projectTypeKey
    },

    status: {
      id: task.fields.status.id,
      nome: task.fields.status.name,
      categoria: task.fields.status.statusCategory.name
    },

    prioridade: {
      id: task.fields.priority.id,
      nome: task.fields.priority.name
    },

    criador: {
      nome: task.fields.creator.displayName,
      accountId: task.fields.creator.accountId
    },

    reporter: {
      nome: task.fields.reporter.displayName,
      accountId: task.fields.reporter.accountId
    },

    responsavel: task.fields.assignee
      ? {
          nome: task.fields.assignee.displayName,
          accountId: task.fields.assignee.accountId
        }
      : null,

    criadoEm: new Date(task.fields.created).toLocaleString("pt-BR", {
      timeZone: "America/Sao_Paulo"
    }),

    atualizadoEm: new Date(task.fields.updated).toLocaleString("pt-BR", {
      timeZone: "America/Sao_Paulo"
    }),

    vencimento: task.fields.duedate,

    labels: task.fields.labels,

    componentes: task.fields.components.map(c => c.name),

    anexos: task.fields.attachment,

    comentarios: {
      quantidade: task.fields.comment.total
    },

    horas: {
      estimativa: task.fields.timeoriginalestimate,
      restante: task.fields.timeestimate,
      trabalhado: task.fields.timespent
    },

    progresso: task.fields.progress,

    observadores: {
      quantidade: task.fields.watches.watchCount,
      assistindo: task.fields.watches.isWatching
    },

    votos: {
      quantidade: task.fields.votes.votes,
      votou: task.fields.votes.hasVoted
    },

    categoria: task.fields.customfield_10249?.value ?? null,
    tecnologia: task.fields.customfield_10248?.value ?? null
  }
}];

const task = $json.body;
const fields = task.fields;

const comentarios = fields.comment.comments ?? [];
const ultimoComentario =
  comentarios.length > 0 ? comentarios[comentarios.length - 1] : null;

return [{
  json: {
    evento: "status_atualizado",

    id: task.id,
    key: task.key,
    url: task.self,

    titulo: fields.summary,
    descricao: fields.description,

    tipo: fields.issuetype.name,

    projeto: {
      key: fields.project.key,
      nome: fields.project.name
    },

    epic: fields.parent
      ? {
          key: fields.parent.key,
          titulo: fields.parent.fields.summary
        }
      : null,

    sprint: fields.customfield_10020?.length
      ? {
          id: fields.customfield_10020[0].id,
          nome: fields.customfield_10020[0].name,
          estado: fields.customfield_10020[0].state,
          inicio: fields.customfield_10020[0].startDate,
          fim: fields.customfield_10020[0].endDate
        }
      : null,

    status: {
      id: fields.status.id,
      nome: fields.status.name,
      categoria: fields.status.statusCategory.name,
      alteradoEm: fields.statuscategorychangedate
    },

    prioridade: fields.priority.name,

    categoria: fields.customfield_10249?.value ?? null,
    tecnologia: fields.customfield_10248?.value ?? null,

    responsavel: fields.assignee?.displayName ?? null,
    criador: fields.creator.displayName,
    solicitante: fields.reporter.displayName,

    criadoEm: new Date(fields.created).toLocaleString("pt-BR", {
      timeZone: "America/Sao_Paulo"
    }),

    atualizadoEm: new Date(fields.updated).toLocaleString("pt-BR", {
      timeZone: "America/Sao_Paulo"
    }),

    comentarios: {
      quantidade: comentarios.length,
      ultimo: ultimoComentario
        ? {
            autor: ultimoComentario.author.displayName,
            texto: ultimoComentario.body,
            criadoEm: new Date(ultimoComentario.created).toLocaleString("pt-BR", {
              timeZone: "America/Sao_Paulo"
            })
          }
        : null
    },

    anexos: fields.attachment.map(a => ({
      nome: a.filename,
      tipo: a.mimeType,
      url: a.content
    })),

    observadores: fields.watches.watchCount,

    progresso: fields.progress,

    labels: fields.labels
  }
}];
